 void editProfile(File f,org.json.JSONObject obj){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(18),dp(8),dp(18),dp(8));CheckBox off=new CheckBox(this);off.setText("إيقاف نافذة وفحص التحديث الاختياري");off.setChecked(!obj.optBoolean("optionalUpdateEnabled"));l.addView(off);EditText brand=field(l,"اسم الهوية",obj.optString("brand")),title=field(l,"العنوان",obj.optString("title")),body=field(l,"الوصف",obj.optString("body")),url=field(l,"رابط قناة Telegram",obj.optString("channelUrl")),button=field(l,"نص الزر",obj.optString("buttonText")),accent=field(l,"لون الزر HEX",obj.optString("accent")),background=field(l,"لون الخلفية HEX",obj.optString("background"));CheckBox ok=new CheckBox(this);ok.setText("أملك صلاحية تعديل هذا التطبيق");l.addView(ok);ScrollView sc=new ScrollView(this);sc.addView(l);AlertDialog d=new AlertDialog.Builder(this).setTitle("تخصيص الواجهة").setView(sc).setNegativeButton("إلغاء",null).setNeutralButton("معاينة",null).setPositiveButton("بناء APK",null).create();d.setOnShowListener(v->{java.util.function.Supplier<org.json.JSONObject> read=()->{try{return WindowProfile.edit(obj,!off.isChecked(),brand.getText().toString(),title.getText().toString(),body.getText().toString(),url.getText().toString(),button.getText().toString(),accent.getText().toString(),background.getText().toString());}catch(Exception e){url.setError(e.getMessage());return null;}};d.getButton(-3).setOnClickListener(x->{org.json.JSONObject n=read.get();if(n!=null)showProfile(n);});d.getButton(-1).setOnClickListener(x->{if(!ok.isChecked()){ok.setError("تأكيد مطلوب");return;}org.json.JSONObject n=read.get();if(n==null)return;d.dismiss();buildProfile(f,n);});});d.show();}
 void showProfile(org.json.JSONObject n){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(24),dp(24),dp(24),dp(24));int bg=Color.parseColor(n.optString("background")),ac=Color.parseColor(n.optString("accent"));l.setBackgroundColor(bg);int fg=android.graphics.Color.luminance(bg)>.45?Color.BLACK:Color.WHITE;l.addView(text(n.optString("brand"),22,fg));l.addView(text(n.optString("title"),20,fg));l.addView(text(n.optString("body"),16,fg));Button b=new Button(this);b.setText(n.optString("buttonText"));b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(ac));b.setTextColor(Color.luminance(ac)>.45?Color.BLACK:Color.WHITE);b.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(n.optString("channelUrl"))));}catch(Exception e){Toast.makeText(this,"تعذر فتح الرابط",Toast.LENGTH_SHORT).show();}});l.addView(b);l.addView(text("معاينة فقط — لا تحقق من عضوية القناة",12,fg));new AlertDialog.Builder(this).setView(l).setNegativeButton("إغلاق",null).show();}
